import{_ as o,Y as n,o as a,c as i,aq as r,H as s}from"./chunks/framework.DpyB0eAw.js";import"./chunks/theme.B8bSfJOi.js";const f=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/home.md","filePath":"en/guide/home.md"}'),l={name:"en/guide/home.md"};function d(u,e,p,c,h,m){const t=n("NolebaseGitChangelog");return a(),i("div",null,[e[0]||(e[0]=r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><blockquote><p>Create more useful tool extensions for Android.</p></blockquote><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>As the Android system continues to evolve, native development demands a growing learning curve. While there are countless utilities available, new fragmentation issues and edge cases emerge endlessly.</p><p>I originally created this project to address the friction I encountered in daily Android development—mostly dealing with cumbersome and outdated system APIs. Guided by the principle of &quot;not reinventing the wheel&quot;, BetterAndroid focuses on enhancing what is already there.</p><p>From UI rendering to system-level interactions, it seamlessly extends native APIs. It is explicitly designed to tackle &quot;black box&quot; scenarios, bridging the gap between official behaviors and the quirks of third-party OEM ROMs.</p><p>Leveraging the power of Kotlin, everything provided here remains strictly non-intrusive. It ensures you can enjoy a smoother, more elegant developer experience without compromising the native ecosystem.</p><p>This library is a culmination of solutions refined across multiple real-world apps, with a significant portion of its core battle-tested and decoupled from my earlier project, <a href="https://github.com/PureReader" target="_blank" rel="noreferrer">PureReader</a>.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>BetterAndroid is born for more modern Android development, and its original meaning is itself.</p><p>We hope that this library can successfully help developers speed up development, improve development quality and experience, and quickly implement the functionality required by apps.</p><h2 id="language-requirement" tabindex="-1">Language Requirement <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;Language Requirement&quot;">​</a></h2><p>It is recommended to use Kotlin as the preferred development language.</p><p>This project is entirely written in Kotlin and is compatible with Java in some parts, but it may not be fully compatible.</p><p>All demo &amp; sample codes in the document will be described using Kotlin, if you don’t know how to use Kotlin at all, you may not get the best experience.</p><h2 id="contribution" tabindex="-1">Contribution <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;Contribution&quot;">​</a></h2><p>The maintenance of this project is inseparable from the support and contributions of all developers.</p><p>This project is currently in its early stages, and there may still be some problems or lack of functionality you need.</p><p>If possible, feel free to submit a PR to contribute features you think are needed to this project or go to <a href="https://github.com/BetterAndroid/BetterAndroid/issues" target="_blank" rel="noreferrer">GitHub Issues</a> to make suggestions to us.</p>',19)),s(t)])}const y=o(l,[["render",d]]);export{f as __pageData,y as default};
